1	#pragma once
2	// Shared infrastructure for the seqtk reimplementation.
3	// Provides FASTA/FASTQ parsing (plain or gzipped), formatted output,
4	// and small shared helpers. Do not modify without coordinating.
5	#include <cstdio>
6	#include <cstdint>
7	#include <string>
8	#include <random>
9	#include <zlib.h>
10	
11	struct SeqRecord {
12	    std::string name;     // up to first whitespace
13	    std::string comment;  // remainder of header line after the first whitespace char
14	    std::string seq;
15	    std::string qual;     // empty for FASTA
16	    bool is_fastq = false;
17	    void clear();
18	};
19	
20	// Streaming reader for FASTA/FASTQ. path == nullptr or "-" reads stdin.
21	// Auto-detects gzip. Lines may be wrapped arbitrarily; records are
22	// re-assembled. Trailing '\r' is stripped from every line.
23	class SeqFile {
24	public:
25	    explicit SeqFile(const char* path);
26	    ~SeqFile();
27	    bool is_open() const { return fp_ != nullptr; }
28	    // Returns 1 on record, 0 on clean EOF, -2 on malformed input.
29	    int next(SeqRecord& r);
30	private:
31	    gzFile fp_ = nullptr;
32	    int lastc_ = -2;        // one-char pushback; -2 = none
33	    int getc();
34	    void ungetc(int c) { lastc_ = c; }
35	    // Reads one logical line (without '\n'; trailing '\r' stripped).
36	    // Returns false if EOF hit with nothing read.
37	    bool read_line(std::string& out);
38	};
39	
40	// Print record to `out`.
41	// line_len <= 0: sequence on a single line; otherwise wrap at line_len.
42	// as_fasta: print FASTA even if qualities exist.
43	void print_record(FILE* out, const SeqRecord& r, int line_len, bool as_fasta);
44	
45	// Complement lookup: A<->T, C<->G (both cases); everything else maps to
46	// the seqtk convention ('N' for non-ACGT in the forward table).
47	extern const char* SEQTK_COMP;
48	
49	// Reverse-complement seq in place; if qual non-null, reverse it in place.
50	void revcomp(std::string& seq, std::string* qual);
51	
52	// The program's RNG: 64-bit Mersenne Twister, matching the reference.
53	// Uniform double in [0,1) drawn as (next() >> 11) * 2^-53.
54	double rand_uniform(std::mt19937_64& g);
55	
56	// Open a plain/gzip file for reading (nullptr/"-": stdin). Returns gzFile
57	// or nullptr.
58	gzFile seqtk_gzopen(const char* path);

1	#include "common.h"
2	#include <cctype>
3	#include <algorithm>
4	#include <cstring>
5	
6	void SeqRecord::clear() {
7	    name.clear(); comment.clear(); seq.clear(); qual.clear();
8	    is_fastq = false;
9	}
10	
11	gzFile seqtk_gzopen(const char* path) {
12	    if (path == nullptr || strcmp(path, "-") == 0)
13	        return gzdopen(0, "r");
14	    return gzopen(path, "r");
15	}
16	
17	SeqFile::SeqFile(const char* path) : fp_(seqtk_gzopen(path)) {}
18	SeqFile::~SeqFile() { if (fp_) gzclose(fp_); }
19	
20	int SeqFile::getc() {
21	    if (lastc_ != -2) { int c = lastc_; lastc_ = -2; return c; }
22	    return gzgetc(fp_);
23	}
24	
25	bool SeqFile::read_line(std::string& out) {
26	    out.clear();
27	    int c;
28	    bool any = false;
29	    while ((c = getc()) >= 0) {
30	        any = true;
31	        if (c == '\n') break;
32	        out.push_back((char)c);
33	    }
34	    if (!any && out.empty()) return false;
35	    if (!out.empty() && out.back() == '\r') out.pop_back();
36	    return true;
37	}
38	
39	int SeqFile::next(SeqRecord& r) {
40	    r.clear();
41	    int c = getc();
42	    if (c < 0) return 0;
43	    if (c != '>' && c != '@') return -2;
44	    // header line
45	    std::string line;
46	    read_line(line);
47	    size_t i = 0;
48	    while (i < line.size() && !isspace((unsigned char)line[i])) ++i;
49	    r.name = line.substr(0, i);
50	    if (i < line.size()) r.comment = line.substr(i + 1);
51	    // sequence lines
52	    for (;;) {
53	        c = getc();
54	        if (c < 0) { r.is_fastq = false; return 1; }
55	        if (c == '+') { // quality follows
56	            r.is_fastq = true;
57	            read_line(line); // discard '+' line content
58	            while (r.qual.size() < r.seq.size()) {
59	                if (!read_line(line)) break;
60	                r.qual += line;
61	            }
62	            return 1;
63	        }
64	        if (c == '>' || c == '@') { ungetc(c); r.is_fastq = false; return 1; }
65	        ungetc(c);
66	        if (!read_line(line)) { return 1; }
67	        r.seq += line;
68	    }
69	}
70	
71	static char comp_table_storage[256];
72	static struct CompTableInit {
73	    CompTableInit() {
74	        memset(comp_table_storage, 0, sizeof(comp_table_storage));
75	        auto set = [](char a, char b) { comp_table_storage[(unsigned char)a] = b; };
76	        set('A','T'); set('C','G'); set('G','C'); set('T','A');
77	        set('a','t'); set('c','g'); set('g','c'); set('t','a');
78	        set('U','A'); set('u','a');
79	        set('M','K'); set('m','k'); set('R','Y'); set('r','y');
80	        set('W','W'); set('w','w'); set('S','S'); set('s','s');
81	        set('Y','R'); set('y','r'); set('K','M'); set('k','m');
82	        set('V','B'); set('v','b'); set('H','D'); set('h','d');
83	        set('D','H'); set('d','h'); set('B','V'); set('b','v');
84	        set('N','N'); set('n','n');
85	    }
86	} comp_table_init;
87	const char* SEQTK_COMP = comp_table_storage;
88	
89	void revcomp(std::string& seq, std::string* qual) {
90	    std::string out;
91	    out.resize(seq.size());
92	    for (size_t i = 0; i < seq.size(); ++i) {
93	        unsigned char c = (unsigned char)seq[seq.size() - 1 - i];
94	        char d = SEQTK_COMP[c];
95	        out[i] = d ? d : 'N';
96	    }
97	    seq.swap(out);
98	    if (qual) std::reverse(qual->begin(), qual->end());
99	}
100	
101	static void write_wrapped(FILE* out, const std::string& s, int line_len) {
102	    if (line_len <= 0 || (int)s.size() <= line_len) {
103	        fwrite(s.data(), 1, s.size(), out);
104	        fputc('\n', out);
105	        return;
106	    }
107	    size_t i = 0;
108	    while (i < s.size()) {
109	        size_t n = s.size() - i < (size_t)line_len ? s.size() - i : (size_t)line_len;
110	        fwrite(s.data() + i, 1, n, out);
111	        fputc('\n', out);
112	        i += n;
113	    }
114	}
115	
116	void print_record(FILE* out, const SeqRecord& r, int line_len, bool as_fasta) {
117	    bool fastq = r.is_fastq && !as_fasta;
118	    fputc(fastq ? '@' : '>', out);
119	    fputs(r.name.c_str(), out);
120	    if (!r.comment.empty()) {
121	        fputc(' ', out);
122	        fputs(r.comment.c_str(), out);
123	    }
124	    fputc('\n', out);
125	    write_wrapped(out, r.seq, line_len);
126	    if (fastq) {
127	        fputs("+\n", out);
128	        write_wrapped(out, r.qual, line_len);
129	    }
130	}
131	
132	double rand_uniform(std::mt19937_64& g) {
133	    return (g() >> 11) * (1.0 / 9007199254740992.0);
134	}

